 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Extend diagonal lines whose color marks form a diagonal pair.
    colors=set(v for row in grid for v in row)
    bg=max(colors,key=lambda x:sum(row.count(x) for row in grid))
    for color in colors-{bg}:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        for i,(r1,c1) in enumerate(pts):
            for r2,c2 in pts[i+1:]:
                dr=r2-r1; dc=c2-c1
                if dr==0 or abs(dr)!=abs(dc):
                    continue
                sr=1 if dr>0 else -1
                sc=1 if dc>0 else -1
                r,c=r1,c1
                while 0<=r-sr<h and 0<=c-sc<w:
                    r-=sr; c-=sc
                while 0<=r<h and 0<=c<w:
                    if out[r][c]==bg:
                        out[r][c]=color
                    r+=sr; c+=sc
                break
            else:
                continue
            break
    return out
